import type { AnchorItem } from './types';

interface ScrollSpyTarget {
  value: string;
  el: Element;
}

/** Returns the element id for a pure in-page hash href (e.g. `#section` -> `section`), or null. */
const hashTargetId = (href?: string): string | null => {
  if (!href || !href.startsWith?.('#') || href.length < 2) {
    return null;
  }

  return href.slice(1);
};

/** Collect `{ value, id }` for every item with an in-page hash href, regardless of resolution. */
const collectHashItems = (items: AnchorItem[] | undefined): { value: string; id: string }[] => {
  const acc: { value: string; id: string }[] = [];

  const walk = (list: AnchorItem[] | undefined) => {
    if (!Array.isArray(list)) {
      return;
    }

    for (const item of list) {
      const id = hashTargetId(item.href);

      if (id) {
        acc.push({ value: item.value, id });
      }

      walk(item.children);
    }
  };

  walk(items);
  return acc;
};

/**
 * Scroll-spy controller for `ks-anchor`: highlights the in-view section while scrolling.
 *
 * Auto-enabled by the component when the active item is uncontrolled and some items point at
 * resolvable in-page hash targets. Targets that have not rendered yet are tracked as pending:
 * while any remain, a MutationObserver watches the document and re-scans so late-rendered
 * sections get picked up; once all resolve it stops watching. The controller never takes over
 * click navigation — it only reports the current section through `setActive`.
 */
export class AnchorScrollSpy {
  private observer?: IntersectionObserver;
  private mutationObserver?: MutationObserver;
  private targets: ScrollSpyTarget[] = [];
  private visible = new Set<Element>();

  constructor(
    private readonly getEl: () => HTMLElement,
    private readonly isControlled: () => boolean,
    private readonly getItems: () => AnchorItem[],
    private readonly setActive: (value: string) => void,
  ) {}

  setup() {
    this.teardown();

    // Controlled active state → the consumer owns it; don't observe.
    if (this.isControlled()) {
      return;
    }

    // No IntersectionObserver in SSR / the spec test runner.
    if (typeof IntersectionObserver === 'undefined') {
      return;
    }

    this.refresh();
  }

  teardown() {
    this.observer?.disconnect();
    this.observer = undefined;
    this.mutationObserver?.disconnect();
    this.mutationObserver = undefined;
    this.targets = [];
    this.visible.clear();
  }

  /** The resolved in-page target element for a clicked item value, if scroll spy tracks it. */
  targetFor(value: string): Element | undefined {
    return this.targets.find((target) => target.value === value)?.el;
  }

  private refresh = () => {
    // Reachable via the MutationObserver after `value` becomes controlled; bail then.
    if (this.isControlled()) {
      this.teardown();
      return;
    }

    const doc = this.getEl().ownerDocument;
    const targets: ScrollSpyTarget[] = [];
    let hasPending = false;

    for (const { value, id } of collectHashItems(this.getItems())) {
      const el = doc.getElementById(id);

      if (el) {
        targets.push({ value, el });
      } else {
        hasPending = true;
      }
    }

    const targetsChanged =
      targets.length !== this.targets.length || targets.some((target, index) => target.el !== this.targets[index]?.el);

    if (targetsChanged) {
      this.observer?.disconnect();
      this.visible.clear();
      this.targets = targets;

      if (targets.length > 0) {
        this.observer = new IntersectionObserver(this.handleIntersect);
        for (const { el } of targets) {
          this.observer.observe(el);
        }
      } else {
        this.observer = undefined;
      }
    }

    if (hasPending) {
      if (!this.mutationObserver && typeof MutationObserver !== 'undefined' && doc.body) {
        this.mutationObserver = new MutationObserver(this.refresh);
        this.mutationObserver.observe(doc.body, { childList: true, subtree: true });
      }
    } else {
      this.mutationObserver?.disconnect();
      this.mutationObserver = undefined;
    }
  };

  private handleIntersect = (entries: IntersectionObserverEntry[]) => {
    for (const entry of entries) {
      if (entry.isIntersecting) {
        this.visible.add(entry.target);
      } else {
        this.visible.delete(entry.target);
      }
    }

    // The first target in item order that is still in view is the current section.
    const current = this.targets.find(({ el }) => this.visible.has(el));

    if (current) {
      this.setActive(current.value);
    }
  };
}
