import {
  Component,
  Element,
  Event,
  type EventEmitter,
  h,
  Host,
  Prop,
  State,
  Watch,
  type ComponentInterface,
} from '@stencil/core';
import { Slot, Slots, Uncontrollable } from '@src/framework/decorators';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { AnchorScrollSpy } from './scroll-spy';
import type { AnchorCollapseOrientation, AnchorItem } from './types';
import { KsIconChevronDown, KsIconChevronUp, KsIconFold, KsIconUnfold } from '@fe-infra/keystone-icons-stencil';

const prefix = 'anchor';
const ROOT_LABEL_PADDING_PX = 24;
const NESTED_LABEL_PADDING_STEP_PX = 12;

/**
 * @part base - The base part.
 * @slot title - Custom rich content for the title row; falls back to the `title` prop.
 */
@Component({
  tag: 'ks-anchor',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsAnchor implements ComponentInterface {
  @Element() el!: HTMLKsAnchorElement;

  /** Title of the anchor component. */
  @Prop() title = '';
  /** Items displayed by the anchor component. */
  @Prop() items: AnchorItem[] = [];
  /** Controlled active item value. */
  @Prop() value?: string;
  /** Default active item value for uncontrolled usage. */
  @Prop() defaultValue?: string;
  @Uncontrollable('value', 'defaultValue', 'ksChange') @State() internalValueState?: string;

  /** Whether the anchor can be collapsed via a toggle button. */
  @Prop() collapsible = false;
  /** Axis the anchor collapses along when `collapsible`. `vertical` collapses the content height and keeps the title row; `horizontal` collapses the whole panel to the toggle button. */
  @Prop() collapseOrientation: AnchorCollapseOrientation = 'vertical';
  /** Controlled collapsed state. */
  @Prop() collapsed?: boolean;
  /** Default collapsed state for uncontrolled usage. */
  @Prop() defaultCollapsed = false;
  @Uncontrollable('collapsed', 'defaultCollapsed', 'ksCollapsedChange') @State() internalCollapsedState?: boolean;

  /** Called when any item is clicked, with the native MouseEvent where `event.preventDefault()` can work. Runs after the item's own `onClick`; use it to handle every item uniformly. */
  @Prop() onItemClick?: (event: MouseEvent, item: AnchorItem) => void;

  /** Emits when the active anchor value changes. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<string>;
  /** Emits when the collapsed state changes. */
  @Event({ bubbles: false, composed: false }) ksCollapsedChange!: EventEmitter<boolean>;

  @Slot({ slotname: 'title' }) private titleSlot!: Slots;

  private wrapperEl?: HTMLDivElement;
  private hasLoaded = false;
  private scrollSpy = new AnchorScrollSpy(
    () => this.el,
    () => this.value !== undefined,
    () => this.items,
    (value) => {
      this.internalValueState = value;
    },
  );

  constructor() {
    registerPluginManager(this.el);
  }

  connectedCallback() {
    if (this.hasLoaded) {
      this.scrollSpy.setup();
    }
  }

  componentDidLoad() {
    this.hasLoaded = true;
    this.scrollSpy.setup();
  }

  disconnectedCallback() {
    this.scrollSpy.teardown();
  }

  /** Re-evaluate scroll spy when the items or the controlled value change. */
  @Watch('items')
  @Watch('value')
  handleScrollSpyInputsChange() {
    this.scrollSpy.setup();
  }

  @Watch('collapsible')
  @Watch('collapseOrientation')
  handleCollapseModeChange() {
    if (this.wrapperEl && !(this.collapsible && this.collapseOrientation === 'vertical')) {
      this.wrapperEl.style.height = '';
    }
  }

  @Watch('internalCollapsedState')
  handleInternalCollapsedStateChange(internalCollapsedState: boolean) {
    const wrapper = this.wrapperEl;

    if (!wrapper || !this.collapsible || this.collapseOrientation !== 'vertical') {
      return;
    }

    if (internalCollapsedState) {
      wrapper.setAttribute('data-collapsed', 'true');
    } else {
      wrapper.removeAttribute('data-collapsed');
    }

    const startHeight = wrapper.getBoundingClientRect().height;
    const endHeight = internalCollapsedState ? 0 : wrapper.scrollHeight;

    const settleHeight = () => {
      wrapper.style.height = internalCollapsedState ? '0px' : 'auto';
    };

    const animation =
      typeof wrapper.animate === 'function'
        ? wrapper.animate([{ height: `${startHeight}px` }, { height: `${endHeight}px` }], {
            duration: 200,
            easing: 'cubic-bezier(0.4, 0, 0.2, 1)',
          })
        : null;

    if (!animation) {
      settleHeight();
      return;
    }

    wrapper.style.height = internalCollapsedState ? '0px' : `${endHeight}px`;
    animation.onfinish = settleHeight;
  }

  private toggleCollapsed = () => {
    this.internalCollapsedState = !this.internalCollapsedState;
  };

  private handleItemClick = (event: MouseEvent) => {
    const target = event.target as HTMLElement;
    const anchor = target.closest<HTMLElement>('a[data-value]');

    if (!anchor) {
      return;
    }

    const { value } = anchor.dataset;
    const item = this.findItemByValue(this.items, value);

    if (!item) {
      return;
    }

    item.onClick?.(event, item);
    this.onItemClick?.(event, item);

    if (!event.defaultPrevented) {
      const spyTargetEl = this.scrollSpy.targetFor(item.value);

      if (spyTargetEl) {
        // Scroll spy is active for this in-page item: replace the instant jump with the
        // browser's native smooth scroll, keep the URL hash in sync, and highlight now.
        event.preventDefault();
        spyTargetEl.scrollIntoView?.({ behavior: 'smooth' });
        this.el.ownerDocument.defaultView?.history?.pushState?.(null, '', item.href ?? null);
        this.internalValueState = item.value;
      } else if (!item.target || item.target === '_self') {
        this.internalValueState = item.value;
      }
    }

    sendActionTracking(this.el, { eventType: 'click', componentParams: { value: item.value } });
  };

  private findItemByValue(items: AnchorItem[] | undefined, value?: string): AnchorItem | undefined {
    if (!Array.isArray(items) || value === undefined) {
      return undefined;
    }

    for (const item of items) {
      if (item.value === value) {
        return item;
      }

      const found = this.findItemByValue(item.children, value);

      if (found) {
        return found;
      }
    }

    return undefined;
  }

  private renderToggleButton() {
    if (!this.collapsible) {
      return null;
    }

    if (this.collapseOrientation === 'horizontal') {
      return (
        <ks-icon-button size="xs" variant="text" data-testid="ks-anchor-index-hide" onClick={this.toggleCollapsed}>
          {this.internalCollapsedState ? <KsIconFold size="14" /> : <KsIconUnfold size="14" />}
        </ks-icon-button>
      );
    }

    return (
      <ks-icon-button size="xs" variant="text" data-testid="ks-anchor-index-collapse" onClick={this.toggleCollapsed}>
        {this.internalCollapsedState ? <KsIconChevronDown size="14" /> : <KsIconChevronUp size="14" />}
      </ks-icon-button>
    );
  }

  private renderItems(items: AnchorItem[] | undefined, depth: number) {
    if (!Array.isArray(items) || items.length === 0) {
      return null;
    }

    const labelStyle = {
      paddingInlineStart: `${ROOT_LABEL_PADDING_PX + depth * NESTED_LABEL_PADDING_STEP_PX}px`,
    };

    return (
      <ul
        class={{
          [`${prefix}__content`]: true,
          [`${prefix}__sub`]: depth > 0,
        }}
        data-depth={depth}
      >
        {items.map((item) => {
          const isActive = this.internalValueState === item.value;

          return (
            <li key={item.value}>
              <a
                class={{
                  [`${prefix}__content-label`]: true,
                  [`${prefix}__content-label--active`]: isActive,
                }}
                href={item.href}
                target={item.target}
                data-value={item.value}
                aria-current={isActive ? 'location' : undefined}
                style={labelStyle}
              >
                <ks-text variant={isActive ? 'titleSm' : 'bodySm'} ellipsis>
                  {item.label}
                </ks-text>
              </a>
              {this.renderItems(item.children, depth + 1)}
            </li>
          );
        })}
      </ul>
    );
  }

  render() {
    const toggleButton = this.renderToggleButton();
    const hasTitleSlot = !!this.titleSlot;
    const shouldRenderTitleRow = !!this.title || hasTitleSlot || !!toggleButton;

    return (
      <Host class="KsAnchor">
        <nav
          class={{
            [prefix]: true,
            [`${prefix}--${this.collapseOrientation}`]: this.collapsible,
            [`${prefix}--hidden`]: !!this.internalCollapsedState,
          }}
          part="base"
          aria-label={this.title || undefined}
        >
          {shouldRenderTitleRow ? (
            <div class={`${prefix}__title`}>
              <slot name="title">
                {this.title ? (
                  <ks-text variant="titleMd" ellipsis>
                    {this.title}
                  </ks-text>
                ) : null}
              </slot>
              {toggleButton}
            </div>
          ) : null}
          <div class={`${prefix}__scroll`}>
            <div
              class={`${prefix}__wrapper`}
              data-collapsed={
                this.collapsible && this.collapseOrientation === 'vertical' && this.internalCollapsedState
                  ? 'true'
                  : undefined
              }
              onClick={this.handleItemClick}
              ref={(el) => (this.wrapperEl = el)}
            >
              {this.renderItems(this.items, 0)}
            </div>
          </div>
        </nav>
      </Host>
    );
  }
}
